using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using QuanLyKho.DTOs;using QuanLyKho.Services;namespace QuanLyKho.Controllers;[ApiController][Route("api/products")][Authorize]public sealed class ProductsController:ControllerBase{readonly ProductService s;public ProductsController(ProductService s)=>this.s=s;[HttpGet]public async Task<IActionResult> GetAll([FromQuery]string? search)=>Ok(await s.GetAllAsync(search));[HttpGet("{id:int}")]public async Task<IActionResult> Get(int id)=>Ok(await s.GetByIdAsync(id));[HttpPost][Authorize(Roles="Admin,Manager")]public async Task<IActionResult> Create(ProductRequest r){var x=await s.CreateAsync(r);return CreatedAtAction(nameof(Get),new{id=x.Id},x);}[HttpPut("{id:int}")][Authorize(Roles="Admin,Manager")]public async Task<IActionResult> Update(int id,ProductRequest r)=>Ok(await s.UpdateAsync(id,r));[HttpDelete("{id:int}")][Authorize(Roles="Admin")]public async Task<IActionResult> Delete(int id){await s.DeleteAsync(id);return NoContent();}}